1	// The auto-merge policy engine (docs/PRINCIPLES.md): may THIS diff land
2	// without a person? A task declares `automerge` — `'nothing'`, `'anything'`,
3	// or a list of named diff classes — and this module turns that declaration plus
4	// the branch's actual diff into a verdict. The call is arithmetic over the diff,
5	// never the session's opinion of its own work: a run cannot talk its way past a
6	// text comparison (the narrow-diff posture, generalized).
7	//
8	// WHAT A POLICY IS FOR. A policy is its author's PREDICTION of the change's
9	// shape — the folders and the kinds of file a request should touch. When the
10	// diff sits inside the prediction, nobody reads it: the code is out the door and
11	// working, and a later PR can improve it. When the diff misses the prediction,
12	// the PR parks for a person, and that park is the mechanism's purpose rather
13	// than its failure. The reviewer here is not checking that the code is perfect;
14	// they are checking the wagon is on the trail — that nothing irreversible
15	// slipped through, and that the change's footprint matches its ask (a wide diff
16	// for a small request is a lesson in separation of concerns, not a defect). So a
17	// policy is written narrow, from the predicted folders, and is never widened to
18	// fit the diff that arrived.
19	//
20	// THE VOCABULARY IS EXTENSIBLE AS DATA. Built-in diff classes live here; a pack
21	// adds its own by shipping a `merge-rules.json` beside its `pack.mjs` — named
22	// path/kind/edit-shape matchers, validated at load, colliding loudly. A policy
23	// then names any rule, built-in or declared, plus the inline `under:<dir>` scope
24	// that carries its own argument, and an unknown name FAILS CLOSED: a policy this
25	// code cannot fully resolve authorizes nothing.
26	//
27	// A LIST IS A UNION, `&&` IS THE INTERSECTION. Listing two terms widens — each
28	// changed file need only be covered by one of them — so the way to say "docs,
29	// but only under this folder" is one `&&` term, never two list entries.
30	//
31	// POLICY SEMANTICS, in evaluation order:
32	//   - `'nothing'`  — never mergeable. `'anything'` — mergeable (the repo's own
33	//     delivery settings still apply downstream, land-pr.mjs).
34	//   - a LIST mixes allow terms and `reject:<name>` terms. A reject matching any
35	//     changed file vetoes the whole diff; otherwise every changed file must be
36	//     covered by some allow term (first listed match wins), and every matched
37	//     rule's whole-diff constraint (e.g. "one code directory") must hold. A list
38	//     with no allow term is an authoring error, not "anything except" — spell
39	//     that as `['anything', 'reject:<name>']`.
40	//   - THE SELF-WIDENING GUARD: under a list policy, a change to the files that
41	//     define policies (`merge-rules.json`, `tasks/<name>/task.json`, this module,
42	//     its work-scope gate) is never coverable unless it is comment-only — a run
43	//     must not be able to grant itself a wider authorization than it started
44	//     with. Only the plain `'anything'` (the trusted lane: the vendored-mount
45	//     converge) can land such a change.
46	//
47	// Two judging surfaces read one resolution path: the landing lane's CLI below
48	// (what the worker doc tells a run to execute before it may merge), and the
49	// `automerge-policy-scope` work check beside this file, which re-evaluates the
50	// same verdict over a branch that stamped the arming trailer.
51	
52	import path from 'node:path';
53	import { readFileSync, existsSync } from 'node:fs';
54	import { COMMENT_CHECKABLE, commentOnly } from '../../../../engine/checks/helpers/code-scanning.mjs';
55	import { FILE_CLASSES } from '../../../../engine/checks/helpers/pattern-rules.mjs';
56	import { isActive } from '../../../../engine/pack_loader/pack-registry.mjs';
57	
58	export { COMMENT_CHECKABLE, commentOnly };
59	
60	export const POLICY_NOTHING = 'nothing';
61	export const POLICY_ANYTHING = 'anything';
62	
63	// The commit-message trailer a run stamps when it intends to land its own PR
64	// under a granular policy — what makes the work-scope gate self-gating: no
65	// trailer, no armed auto-merge, nothing to judge. The policy expression is the
66	// string form below (`a;b;reject:c`).
67	export const AUTOMERGE_TRAILER = 'Claudinite-Automerge-Policy';
68	export const AUTOMERGE_TRAILER_RE = /^Claudinite-Automerge-Policy:[ \t]*(\S+)[ \t]*$/m;
69	
70	// --- path classification (shared with narrow-diff.mjs, which re-exports it) ---
71	
72	const DOC_EXTENSIONS = new Set(['.md', '.markdown', '.txt', '.rst']);
73	
74	const TEST_DIRS = new Set(['test', 'tests', '__tests__', 'spec', 'specs', 'fixtures', 'testdata']);
75	
76	// A path's kind, from the path alone: 'doc', 'test', or 'code'. Directory names
77	// are matched on whole segments (`tests/`), never on substrings, so `latest/` is
78	// not a test directory; file names are matched on the conventions every ecosystem
79	// here shares.
80	export function classifyPath(file) {
81	  const segments = file.split('/');
82	  const name = segments[segments.length - 1];
83	  if (segments.slice(0, -1).some((seg) => TEST_DIRS.has(seg) || seg.endsWith('-tests') || seg.endsWith('_tests'))) return 'test';
84	  if (/(^|[.\-_])(test|tests|spec)[.\-_]/i.test(name) || /^test_/i.test(name)) return 'test';
85	  if (DOC_EXTENSIONS.has(path.extname(name).toLowerCase())) return 'doc';
86	  return 'code';
87	}
88	
89	// --- diff entries -------------------------------------------------------------
90	
91	// One changed file with both contents: null `before` = added, null `after` =
92	// deleted. Everything below judges these, so a caller with another diff source
93	// (the work-scope context) builds the same shape.
94	export const changeKindOf = ({ before, after }) =>
95	  (before == null ? 'added' : after == null ? 'deleted' : 'modified');
96	
97	// Only line removals (and nothing else): the after-lines are an ordered
98	// subsequence of the before-lines. Deliberately order-preserving — a reorder is
99	// an edit, not a removal — and a whole-file deletion is every line removed.
100	export function removalsOnly(before, after) {
101	  return shrinkOnly(before, after, (line, original) => line === original);
102	}
103	
104	// Removals, plus in-line TRIMS: every surviving line either equals a line it
105	// replaces or is a character-subsequence of one — a line cut in half, a word
106	// struck from its middle, a truncation closed with a period the original
107	// already held. What can never pass is growth: no new line, and no character a
108	// replaced line did not already carry in order. The alignment is greedy and
109	// backtrack-free, so a pathological reshuffle can read as not-a-trim — that
110	// end fails safe (the diff parks for review).
111	export function trimsOnly(before, after) {
112	  return shrinkOnly(before, after, isCharSubsequence);
113	}
114	
115	function shrinkOnly(before, after, lineSatisfies) {
116	  if (after == null) return true;
117	  if (before == null) return false;
118	  const from = before.split('\n');
119	  const to = after.split('\n');
120	  let i = 0;
121	  for (const line of to) {
122	    while (i < from.length && !lineSatisfies(line, from[i])) i += 1;
123	    if (i === from.length) return false;
124	    i += 1;
125	  }
126	  return true;
127	}
128	
129	function isCharSubsequence(needle, hay) {
130	  let i = 0;
131	  for (const c of needle) {
132	    i = hay.indexOf(c, i);
133	    if (i === -1) return false;
134	    i += 1;
135	  }
136	  return true;
137	}
138	
139	const isCommentOnlyChange = (e) => changeKindOf(e) === 'modified' && commentOnly(e.file, e.before, e.after);
140	
141	// --- the rule registry --------------------------------------------------------
142	// A rule is `{ name, appliesTo(entry) }` plus, for the whole-diff rules, a
143	// `constraint(coveredEntries)` returning null or the reason it fails. `appliesTo`
144	// answers both roles a policy can use the name in: as an allow term it covers the
145	// files it applies to, as a `reject:` term it vetoes on them.
146	
147	// The two code-locality rules deliberately do NOT apply to a comment-only code
148	// file (mirroring narrowVerdict): a comment edit is `comment-only-changes`'
149	// business, and counting it toward the file/directory budget would fail a diff
150	// the policy's author plainly meant to allow.
151	const isRealCodeChange = (e) => classifyPath(e.file) === 'code' && !isCommentOnlyChange(e);
152	
153	export const BUILTIN_MERGE_RULES = new Map([
154	  ['doc-changes', {
155	    appliesTo: (e) => changeKindOf(e) !== 'deleted' && classifyPath(e.file) === 'doc',
156	  }],
157	  ['readme-changes', {
158	    appliesTo: (e) => changeKindOf(e) !== 'deleted' && path.basename(e.file).toLowerCase() === 'readme.md',
159	  }],
160	  ['comment-only-changes', {
161	    appliesTo: isCommentOnlyChange,
162	  }],
163	  // Every change kind, a deletion included: a policy naming this class predicted
164	  // the test tree as the change's shape, and a test file removed or renamed
165	  // inside that tree is that same shape — a rename lands as a delete beside an
166	  // add, and parking it asked a reviewer for a decision nobody made.
167	  ['test-changes', {
168	    appliesTo: (e) => classifyPath(e.file) === 'test',
169	  }],
170	  ['markdown-line-removals', {
171	    appliesTo: (e) => e.file.toLowerCase().endsWith('.md')
172	      && changeKindOf(e) !== 'added' && removalsOnly(e.before, e.after),
173	  }],
174	  // The trim superset of the rule above: whole-line removals plus in-line trims
175	  // (trimsOnly) — for a prune allowed to cut a line down, never to grow one.
176	  ['markdown-trims', {
177	    appliesTo: (e) => e.file.toLowerCase().endsWith('.md')
178	      && changeKindOf(e) !== 'added' && trimsOnly(e.before, e.after),
179	  }],
180	  ['file-additions', {
181	    appliesTo: (e) => changeKindOf(e) === 'added',
182	  }],
183	  ['generated-file-changes', {
184	    appliesTo: (e) => changeKindOf(e) !== 'deleted' && path.basename(e.file).includes('GENERATED'),
185	  }],
186	  // The language-scoped class, matching ANY change to a JavaScript-family file —
187	  // built in mostly for its `reject:` use ("nothing may touch the JS"), which is
188	  // why it applies to every change kind. Its file set is the checks engine's own
189	  // JavaScript class, so the two surfaces cannot disagree on what counts.
190	  ['javascript-changes', {
191	    appliesTo: (e) => FILE_CLASSES.javascriptFiles.test(e.file),
192	  }],
193	  ['single-file-code-changes', {
194	    appliesTo: isRealCodeChange,
195	    constraint: (covered) => {
196	      const files = [...new Set(covered.map((e) => e.file))].sort();
197	      return files.length <= 1 ? null : `code changed in ${files.length} files: ${files.join(', ')}`;
198	    },
199	  }],
200	  ['single-folder-code-changes', {
201	    appliesTo: isRealCodeChange,
202	    constraint: (covered) => {
203	      const dirs = [...new Set(covered.map((e) => path.dirname(e.file)))].sort();
204	      return dirs.length <= 1 ? null : `code changed in ${dirs.length} directories: ${dirs.join(', ')}`;
205	    },
206	  }],
207	]);
208	
209	// Composites expand into their member allow terms — `narrow-diff` is the queue's
210	// historical `Merge: if-narrow` shape. Slightly stricter than the retired
211	// narrowVerdict on purpose: a DELETED doc is no longer silently allowed
212	// (deciding a document should not exist is a reviewed change — the
213	// improve-comments-scope lesson), which fails toward a parked PR, never a merge.
214	export const COMPOSITE_POLICIES = new Map([
215	  ['narrow-diff', ['doc-changes', 'test-changes', 'comment-only-changes', 'single-folder-code-changes']],
216	]);
217	
218	// --- the inline path scope (`under:<dir>`) ------------------------------------
219	
220	// A rule name that carries its own argument: `under:packs/claudinite-tasks`
221	// covers every change inside that directory. It exists because a scope is
222	// usually per-request — the one folder an ad-hoc ask or a task is confined to —
223	// where a named merge-rules.json rule is per-pack and costs a commit to add.
224	//
225	// It covers any change KIND inside the directory (added, modified, deleted):
226	// "any change under this folder" reads as literally any. And it scopes rather
227	// than widens — a changed file outside the folder is covered by no allow term,
228	// so a diff that strays parks — with POLICY_SOURCES below still absolute, so a
229	// folder scope cannot reach the files that define policies even when they sit
230	// inside it.
231	export const UNDER_PREFIX = 'under:';
232	
233	const PATH_SEGMENT_RE = /^[A-Za-z0-9._-]+$/;
234	
235	// The rule an `under:<dir>` term denotes, or null when `<dir>` is not a usable
236	// repo-relative directory (absolute, empty, or carrying a `.`/`..` segment).
237	// Null is a verdict: an unresolvable scope makes the whole policy invalid, which
238	// authorizes nothing — the same fail-closed answer an unknown rule name gets.
239	export function underRule(term) {
240	  const dir = term.slice(UNDER_PREFIX.length).replace(/\/+$/, '');
241	  const segments = dir.split('/');
242	  if (!dir || segments.some((seg) => !PATH_SEGMENT_RE.test(seg) || seg === '.' || seg === '..')) return null;
243	  const prefix = `${dir}/`;
244	  return { name: term, appliesTo: (e) => e.file.startsWith(prefix) };
245	}
246	
247	// --- the `&&` intersection ----------------------------------------------------
248	
249	// A policy list is a UNION: adding a term widens what may land. `&&` is the one
250	// narrowing operator — `under:product-wiki&&doc-changes` covers a file only when
251	// every part covers it, so it reads as "docs, and only under that folder".
252	//
253	// Whitespace around it is accepted wherever a human writes one (an issue's
254	// `Automerge:` line, a task declaration) and canonicalized away by
255	// `policyExpression`, so what rides the commit trailer stays one whitespace-free
256	// token. `&` is not a legal character in a rule name or an `under:` path, so the
257	// operator can never be read as part of a term.
258	export const CONJUNCTION = '&&';
259	
260	const conjunctionParts = (term) => term.split(CONJUNCTION).map((p) => p.trim());
261	
262	// --- pack-declared rules (merge-rules.json) -----------------------------------
263	
264	export const MERGE_RULES_FILE = 'merge-rules.json';
265	
266	const RULE_NAME_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/;
267	const DECLARED_KEYS = ['name', 'pathMatching', 'excludePathMatching', 'changeKinds', 'editShape', 'coversMountPolicySources'];
268	const CHANGE_KINDS = ['added', 'modified', 'deleted'];
269	const EDIT_SHAPES = ['any', 'removals-only', 'comment-only'];
270	
271	// Regex-as-string in the `/body/flags` form declared-checks.json already uses —
272	// the same inline parse pattern-rules.mjs applies (this module cannot import the
273	// checks engine's private compiler, so the six lines live here and point there).
274	function compileRegex(raw, where) {
275	  const m = /^\/(.*)\/([a-z]*)$/s.exec(String(raw));
276	  if (!m) throw new Error(`${where}: ${JSON.stringify(raw)} is not a /pattern/ regex string`);
277	  return new RegExp(m[1], m[2]);
278	}
279	
280	// One declared rule compiled into the registry shape. Every key is validated and
281	// `changeKinds`/`editShape` are REQUIRED — a matcher whose reach is defaulted is
282	// a matcher nobody decided (the corpus' explicit-over-default rule).
283	export function compileDeclaredRule(spec, where) {
284	  if (spec === null || typeof spec !== 'object' || Array.isArray(spec)) {
285	    throw new Error(`${where}: a merge rule is an object, not ${JSON.stringify(spec)}`);
286	  }
287	  for (const key of Object.keys(spec)) {
288	    if (!DECLARED_KEYS.includes(key)) {
289	      throw new Error(`${where}: "${key}" is not a merge-rule key — the vocabulary is: ${DECLARED_KEYS.join(', ')}`);
290	    }
291	  }
292	  if (typeof spec.name !== 'string' || !RULE_NAME_RE.test(spec.name)) {
293	    throw new Error(`${where}: a merge rule needs a kebab-case "name"`);
294	  }
295	  const pathMatching = compileRegex(spec.pathMatching, `${where} (${spec.name}).pathMatching`);
296	  const exclude = spec.excludePathMatching === undefined
297	    ? null : compileRegex(spec.excludePathMatching, `${where} (${spec.name}).excludePathMatching`);
298	  if (!Array.isArray(spec.changeKinds) || !spec.changeKinds.length
299	      || spec.changeKinds.some((k) => !CHANGE_KINDS.includes(k))) {
300	    throw new Error(`${where} (${spec.name}): "changeKinds" is a non-empty subset of ${CHANGE_KINDS.join(', ')}`);
301	  }
302	  if (!EDIT_SHAPES.includes(spec.editShape)) {
303	    throw new Error(`${where} (${spec.name}): "editShape" must be one of ${EDIT_SHAPES.join(', ')} — declared, never defaulted`);
304	  }
305	  // The one key that may relax the self-widening guard, and only for files under
306	  // the VENDORED MOUNT (see POLICY_SOURCES below): declaring it is an owner
307	  // saying "this task may rewrite the mount, policy definitions included" — the
308	  // adoption/converge grant. `true` only, so it cannot be half-declared.
309	  if (spec.coversMountPolicySources !== undefined && spec.coversMountPolicySources !== true) {
310	    throw new Error(`${where} (${spec.name}): "coversMountPolicySources" takes only \`true\` — omit it otherwise`);
311	  }
312	  return {
313	    name: spec.name,
314	    coversMountPolicySources: spec.coversMountPolicySources === true,
315	    appliesTo(e) {
316	      if (!pathMatching.test(e.file) || (exclude && exclude.test(e.file))) return false;
317	      if (!spec.changeKinds.includes(changeKindOf(e))) return false;
318	      if (spec.editShape === 'removals-only') return changeKindOf(e) !== 'added' && removalsOnly(e.before, e.after);
319	      if (spec.editShape === 'comment-only') return isCommentOnlyChange(e);
320	      return true;
321	    },
322	  };
323	}
324	
325	// The merge rules the ACTIVE packs declare, keyed by name. `packs` are discovered
326	// pack objects (each with `.dir`), `config` the normalized repo config — the pair
327	// both judging surfaces already hold. A broken declaration or a name collision is
328	// an ERROR entry, never a silent drop: a policy naming the broken rule must fail
329	// closed, and the error text is what gets it fixed.
330	export function declaredMergeRules(packs, config) {
331	  const rules = new Map();
332	  const errors = [];
333	  for (const pack of (packs ?? []).filter((p) => p.dir && isActive(p, config))) {
334	    const file = path.join(pack.dir, MERGE_RULES_FILE);
335	    if (!existsSync(file)) continue;
336	    const where = `${pack.id}/${MERGE_RULES_FILE}`;
337	    let specs;
338	    try {
339	      specs = JSON.parse(readFileSync(file, 'utf8'));
340	      if (!Array.isArray(specs)) throw new Error('the file must hold an array of rule objects');
341	    } catch (e) {
342	      errors.push(`${where}: ${e.message}`);
343	      continue;
344	    }
345	    for (const spec of specs) {
346	      try {
347	        const rule = compileDeclaredRule(spec, where);
348	        if (BUILTIN_MERGE_RULES.has(rule.name) || COMPOSITE_POLICIES.has(rule.name) || rules.has(rule.name)) {
349	          throw new Error(`rule name "${rule.name}" is already taken — merge-rule names are one flat namespace`);
350	        }
351	        rules.set(rule.name, rule);
352	      } catch (e) {
353	        errors.push(e.message.startsWith(where) ? e.message : `${where}: ${e.message}`);
354	      }
355	    }
356	  }
357	  return { rules, errors };
358	}
359	
360	// --- policy parsing -----------------------------------------------------------
361	
362	const TERM_NAME_RE = /^(under:\S+|[a-z0-9]+(-[a-z0-9]+)*)$/;
363	
364	// A policy, normalized from any surface it rides — the declaration's string or
365	// array, the item's `Merge:` field, the commit trailer's `a;b;reject:c` — into
366	// { kind: 'nothing' | 'anything' } or { kind: 'rules', allow, reject } or
367	// { kind: 'invalid', reason }. Invalid is a verdict-shaped answer on purpose:
368	// every consumer treats it as "authorizes nothing", loudly.
369	export function normalizePolicy(raw) {
370	  if (raw == null) return { kind: POLICY_NOTHING };
371	  const terms = Array.isArray(raw)
372	    ? raw.map((t) => String(t).trim())
373	    : String(raw).trim().split(';').map((t) => t.trim());
374	  if (terms.length === 1) {
375	    const one = terms[0].toLowerCase();
376	    if (one === POLICY_NOTHING || one === '') return { kind: POLICY_NOTHING };
377	    if (one === POLICY_ANYTHING) return { kind: POLICY_ANYTHING };
378	    // The queue's historical spellings for its one pre-policy authorization.
379	    if (one === 'if-narrow' || one === 'yes' || one === 'true') return normalizePolicy(['narrow-diff']);
380	  }
381	  const allow = [];
382	  const reject = [];
383	  for (const term of terms) {
384	    const isReject = term.startsWith('reject:');
385	    const parts = conjunctionParts(isReject ? term.slice('reject:'.length) : term);
386	    for (const part of parts) {
387	      if (!TERM_NAME_RE.test(part)) {
388	        return { kind: 'invalid', reason: `"${term}" is not a policy term (rule names or under:<dir>, joined with && and optionally reject:-prefixed)` };
389	      }
390	      if (part.startsWith(UNDER_PREFIX) && !underRule(part)) {
391	        return { kind: 'invalid', reason: `"${part}" names no usable repo-relative directory — spell it under:packs/some-pack` };
392	      }
393	    }
394	    // A composite is itself a union, so intersecting one is ambiguous, and the
395	    // whole-policy words mean nothing narrowed: both are authoring errors.
396	    if (parts.length > 1) {
397	      const notIntersectable = parts.find((p) => COMPOSITE_POLICIES.has(p) || p === POLICY_ANYTHING || p === POLICY_NOTHING);
398	      if (notIntersectable) {
399	        return { kind: 'invalid', reason: `"${notIntersectable}" cannot sit in an && term — intersect specific rules` };
400	      }
401	    }
402	    const name = parts.join(CONJUNCTION);
403	    if (isReject) {
404	      if (COMPOSITE_POLICIES.has(name)) return { kind: 'invalid', reason: `"${term}" rejects a composite — name the specific rules to reject` };
405	      reject.push(name);
406	    } else if (name === POLICY_ANYTHING) {
407	      allow.push(name);
408	    } else if (name === POLICY_NOTHING) {
409	      return { kind: 'invalid', reason: `"nothing" cannot sit in a rule list — it is a whole policy of its own` };
410	    } else {
411	      allow.push(...(COMPOSITE_POLICIES.get(name) ?? [name]));
412	    }
413	  }
414	  if (!allow.length) {
415	    return { kind: 'invalid', reason: 'the policy lists no allow term — "anything except X" is spelled ["anything", "reject:X"]' };
416	  }
417	  return { kind: 'rules', allow: [...new Set(allow)], reject: [...new Set(reject)] };
418	}
419	
420	// The string form of a declared policy — what rides the commit trailer and the
421	// worker's CLI invocation. Inverse of normalizePolicy for every legal value, and
422	// the one place whitespace around `&&` is collapsed, which is what keeps the
423	// stamped trailer a single whitespace-free token.
424	export const policyExpression = (policy) =>
425	  (Array.isArray(policy) ? policy : String(policy ?? POLICY_NOTHING).split(';'))
426	    .map((t) => conjunctionParts(String(t).trim()).join(CONJUNCTION))
427	    .join(';');
428	
429	// --- the verdict --------------------------------------------------------------
430	
431	// The files no granular policy may cover except as comment-only edits: the
432	// sources the policy machinery itself is read from. Whatever an allow rule says,
433	// a run authorized by a list must not be able to rewrite what it is authorized
434	// to do. (`'anything'` — the vendored-converge lane — is deliberately exempt:
435	// the mount refresh replaces these files wholesale, and that lane's trust is the
436	// repo's delivery setting, not a diff class.)
437	//
438	// One narrow relaxation: such a file UNDER THE VENDORED MOUNT may be covered by
439	// a declared rule carrying `coversMountPolicySources` — the shape an adoption
440	// re-vendor has, where policy files arrive canon-authored inside the pack trees
441	// it copies. The flag rides merge-rules.json, which is itself guarded and
442	// owner-committed, so a run cannot grant it to itself; repo-owned policy
443	// sources (everything outside the mount) stay absolute.
444	const POLICY_SOURCES = /(^|\/)(merge-rules\.json|merge-policy\.mjs|workRules\/automerge-policy-scope\.mjs|tasks\/[^/]+\/task\.json)$/;
445	const VENDORED_MOUNT = /^\.claudinite\/shared\//;
446	
447	// The whole verdict over a diff. `entries` are `{ file, before, after }` (null
448	// side = added/deleted); `declaredRules` a Map from declaredMergeRules, with its
449	// `errors` passed through so a broken declaration fails any policy that names
450	// the broken pack's rule set. Returns { mergeable, why, files, problems }:
451	// `files` carries one line per changed file (its covering rule, or its
452	// violation), `problems` each refusal as { file, what } — file null for a
453	// whole-diff refusal — because a run that parks has to say what it parked over.
454	export function policyVerdict({ policy, entries, declaredRules = new Map(), ruleErrors = [] }) {
455	  const refuse = (problems, files = []) => ({
456	    mergeable: false, why: problems.map((p) => p.what).join('; '), files, problems,
457	  });
458	  const norm = normalizePolicy(policy);
459	  if (norm.kind === 'invalid') return refuse([{ file: null, what: `invalid policy: ${norm.reason}` }]);
460	  if (norm.kind === POLICY_NOTHING) {
461	    return refuse([{ file: null, what: 'the policy authorizes nothing to auto-merge' }]);
462	  }
463	  if (norm.kind === POLICY_ANYTHING) {
464	    return { mergeable: true, why: 'the policy authorizes any diff (the repo\'s delivery settings still apply)', files: [], problems: [] };
465	  }
466	  if (!entries.length) {
467	    return refuse([{ file: null, what: 'this branch changes nothing against the base — there is nothing to merge' }]);
468	  }
469	
470	  const resolveOne = (name) => (name.startsWith(UNDER_PREFIX)
471	    ? underRule(name)
472	    : BUILTIN_MERGE_RULES.get(name) ?? declaredRules.get(name) ?? null);
473	  // An `&&` term is one rule that every part must agree on — for coverage and
474	  // for the whole-diff constraints alike. It deliberately carries no
475	  // `coversMountPolicySources`: that grant belongs to the declared rule that was
476	  // committed with it, never to an expression composed around it.
477	  const resolve = (name) => {
478	    if (!name.includes(CONJUNCTION)) return resolveOne(name);
479	    const parts = name.split(CONJUNCTION).map(resolveOne);
480	    if (parts.some((r) => !r)) return null;
481	    return {
482	      name,
483	      appliesTo: (e) => parts.every((r) => r.appliesTo(e)),
484	      constraint: (covered) => parts.map((r) => r.constraint?.(covered) ?? null).find(Boolean) ?? null,
485	    };
486	  };
487	  const unknown = [...norm.allow, ...norm.reject].filter((n) => n !== POLICY_ANYTHING && !resolve(n));
488	  if (unknown.length) {
489	    const errs = ruleErrors.length ? ` (rule declarations also failed to load: ${ruleErrors.join('; ')})` : '';
490	    return refuse([{ file: null, what: `unresolved rule name(s): ${unknown.join(', ')} — an unknown rule authorizes nothing${errs}` }]);
491	  }
492	
493	  const files = [];
494	  const problems = [];
495	  const coveredBy = new Map(); // allow name -> entries it covered
496	  for (const entry of entries) {
497	    const { file } = entry;
498	    if (POLICY_SOURCES.test(file) && !isCommentOnlyChange(entry)) {
499	      const mountCoverer = VENDORED_MOUNT.test(file)
500	        && norm.allow.find((n) => resolve(n)?.coversMountPolicySources && resolve(n).appliesTo(entry));
501	      if (!mountCoverer) {
502	        files.push({ file, verdict: 'policy-source' });
503	        problems.push({ file, what: `${file} defines auto-merge policy itself — no granular policy may change it` });
504	        continue;
505	      }
506	      // Exempted: it falls through to the ordinary reject/coverage flow below,
507	      // so a reject term still vetoes it and the flagged rule still has to
508	      // cover it on its own terms.
509	    }
510	    const rejectedBy = norm.reject.find((n) => resolve(n).appliesTo(entry));
511	    if (rejectedBy) {
512	      files.push({ file, verdict: `rejected:${rejectedBy}` });
513	      problems.push({ file, what: `${file} matches reject:${rejectedBy}` });
514	      continue;
515	    }
516	    const coverer = norm.allow.find((n) => n === POLICY_ANYTHING || resolve(n).appliesTo(entry));
517	    if (coverer === undefined) {
518	      files.push({ file, verdict: 'uncovered' });
519	      problems.push({ file, what: `${file} (${changeKindOf(entry)} ${classifyPath(entry.file)}) is covered by no allow term` });
520	      continue;
521	    }
522	    files.push({ file, verdict: `covered:${coverer}` });
523	    if (!coveredBy.has(coverer)) coveredBy.set(coverer, []);
524	    coveredBy.get(coverer).push(entry);
525	  }
526	  for (const [name, covered] of coveredBy) {
527	    const failed = resolve(name)?.constraint?.(covered) ?? null;
528	    if (failed) problems.push({ file: null, what: `${name}: ${failed}` });
529	  }
530	
531	  return problems.length
532	    ? refuse(problems, files)
533	    : { mergeable: true, why: `every changed file is covered (${[...coveredBy.keys()].join(', ')})`, files, problems: [] };
534	}
535	
536	// --- the diff against a base ref (shared with narrow-diff.mjs) ----------------
537	
538	// `stderr: ignore` because the ONE expected failure here — `git show` on a path
539	// that does not exist at that ref — is how an added or deleted file answers, and
540	// letting git narrate it once per such file buries the verdict the caller reads.
